import {returnDate,weekend} from './engine.js';
document.documentElement.dataset.live='1';
const $=s=>document.querySelector(s),money=n=>'¥'+Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2});
const cities=[['xiamen','厦门','海边'],['chengdu','成都','美食'],['guilin','桂林','山野'],['chongqing','重庆','美食'],['haikou','海口','海边'],['kunming','昆明','山野'],['dali','大理','山野'],['qingdao','青岛','海边']].map(([id,city,tag])=>({id,city,tag}));
let job=null,tag='全部',saved=false,busy=false,available=false;let favorites=[];try{favorites=JSON.parse(localStorage.getItem('weekend-favorites'))||[]}catch{}if(!Array.isArray(favorites))favorites=[];
const note=$('.data-note');note.replaceChildren();const noteText=document.createElement('span');note.append(noteText);
const make=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!==undefined)e.textContent=text;return e};
function statusText(r){return !r?'尚未查询':({queued:'等待查询',running:'正在查询去程 / 返程…',error:'本次未取得报价',no_match:'没有符合条件的组合',success:'飞猪 FlyAI · 成人1人经济舱'})[r.status]}
function render(){const origin=$('#origin').value,budget=+$('#budget').value;$('#budget-value').textContent=money(budget);$('#fav-count').textContent=favorites.length;$('#section-title').textContent=saved?'收藏目的地的真实报价':'全部目的地 · FlyAI 实时报价';let list=cities.filter(c=>c.city!==origin&&(tag==='全部'||c.tag===tag||(tag==='城市'&&['成都','重庆','昆明','青岛','厦门'].includes(c.city)))&&(!saved||favorites.includes(c.id)));const result=c=>job?.results?.[c.city];if($('#sort').value==='price')list.sort((a,b)=>{const x=result(a)?.best,y=result(b)?.best;return (x?.total===null?1:0)-(y?.total===null?1:0)||(x?.total??x?.fare??Infinity)-(y?.total??y?.fare??Infinity)});$('#result-summary').textContent=`${origin}出发 · ${$('#departure').value} — ${returnDate($('#departure').value)} · ${job?`${job.completed}/${Object.keys(job.results).length} 个目的地已查询`:'尚未查询'} · 当前仅采集飞猪直飞`;$('#cards').replaceChildren();$('#empty').hidden=list.length>0;
for(const c of list){const r=result(c),p=r?.best,stale=r?.collectedAt&&Date.now()-Date.parse(r.collectedAt)>300000,card=make('article','card'),art=make('div','art');art.style.setProperty('--sky','#d5e1d8');art.style.setProperty('--sun','#ead5a1');art.style.setProperty('--land','#94b3a0');art.append(make('span','big-city',c.city),make('span','art-tag',statusText(r)));const fav=make('button','save'+(favorites.includes(c.id)?' saved':''),favorites.includes(c.id)?'♥':'♡');fav.setAttribute('aria-label','收藏'+c.city);fav.onclick=()=>{favorites=favorites.includes(c.id)?favorites.filter(id=>id!==c.id):[...favorites,c.id];localStorage.setItem('weekend-favorites',JSON.stringify(favorites));render()};art.append(fav);const body=make('div','card-body');body.append(make('h3','',c.city),make('p','description',c.tag+' · '+statusText(r)));
if(p){body.append(make('p','live-flights',`去 ${p.outbound.number} ${p.outbound.departureTime} → ${p.outbound.arrivalTime}${p.outbound.nextDay?'（次日）':''}`),make('p','live-flights',`回 ${p.inbound.number} ${p.inbound.departureTime} → ${p.inbound.arrivalTime}`));const price=make('div','price');price.append(make('small','',stale?'上次查询价 · 已超过5分钟':'本次采集的往返列表价 / 成人1人'),make('strong','',p.total===null?money(p.fare)+' + 税费待核实':money(p.total)));body.append(price,make('p','muted',p.total===null?`往返票面 ${money(p.fare)}，税费未完整提取`:`票面 ${money(p.fare)} + 机建燃油 ${money(Math.round((p.total-p.fare)*100)/100)}`));if((p.total??p.fare)>budget)body.append(make('p','over-budget',`超出机票预算 ${money((p.total??p.fare)-budget)}`));body.append(make('small','muted','采集 '+new Date(r.collectedAt).toLocaleTimeString('zh-CN',{hour12:false})+' · 列表价未进入购买页核验'))}else body.append(make('p','price-status',r?.message||'点击上方“查询全部目的地”获取当前网页报价。'));const btn=make('button','detail',p?'查看航班与去核价 ↗':'查看查询状态 ↗');btn.onclick=()=>details(c,r);body.append(btn);card.append(art,body);$('#cards').append(card)}}
function details(c,r){const box=$('#trip-content');box.replaceChildren(make('p','eyebrow','LIVE PAGE PRICES'),make('h2','',$('#origin').value+' ↔ '+c.city));box.append(make('p','muted',statusText(r)),make('p','muted','以下是本次返回候选中的价格，不保证覆盖全部航班；两张单程票的组合不等于往返套票。'));if(r?.best){for(const [i,p] of (r.options||[]).entries()){const row=make('div','trip-summary');row.append(make('b','',`方案 ${i+1} · ${p.total===null?money(p.fare)+' + 税费待核实':money(p.total)}`));for(const f of [p.outbound,p.inbound])row.append(make('p','',`${f.date} ${f.number} · ${f.departureTime} → ${f.arrivalTime}${f.nextDay?'（次日）':''}`),make('p','muted',`${f.departureAirport} → ${f.arrivalAirport}`),make('p','muted',`票面 ${money(f.fare)} · ${f.tax===null?'税费未知':f.rawFee}`));const purchases=make('div','platforms');for(const [label,f] of [['购买此方案去程',p.outbound],['购买此方案返程',p.inbound]]){const a=make('a','',label+' ↗');a.href=f.url;a.target='_blank';a.rel='noopener noreferrer';purchases.append(a)}row.append(purchases);box.append(row)}}else box.append(make('p','price-status',r?.message||'尚未查询'));if(r?.collectedAt)box.append(make('p','muted','采集时间：'+new Date(r.collectedAt).toLocaleString('zh-CN')));const links=make('div','platforms');for(const [name,url] of [['飞猪去程购买入口',r?.best?.outbound?.url||r?.outUrl],['飞猪返程购买入口',r?.best?.inbound?.url||r?.backUrl]])if(url){const a=make('a','',name+' ↗');a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a)}box.append(links,make('p','muted','平台页面可能要求登录或验证码。请核对卖家、行李、退改、人数与最终支付金额。'));$('#trip-dialog').showModal()}
function lock(v){busy=v;for(const id of ['origin','departure','earliest','latest'])$('#'+id).disabled=v;$('.search-submit').disabled=v;$('.search-submit').textContent=v?'正在逐个查询…':'查询全部目的地 ↗'}
async function poll(id){try{const res=await fetch('/api/search/'+encodeURIComponent(id),{cache:'no-store'});if(!res.ok)throw Error('查询记录已失效，请重新查询');job=await res.json();try{localStorage.setItem('weekend-last-live',JSON.stringify(job))}catch{}noteText.textContent=`飞猪 FlyAI采集 · ${job.completed}/${Object.keys(job.results).length} 个目的地完成。每个目的地分别查去程和返程，通常需要数分钟；价格仅代表查询时刻。当前为免 Key 体验模式，候选可能受限；税费未返回时不估算。`;render();if(job.status==='complete'){lock(false);noteText.textContent+=' 本批次已完成，可点击查询刷新。'}else setTimeout(()=>poll(id),1800)}catch(e){lock(false);noteText.textContent=e.message}}
$('#search-form').onsubmit=async e=>{e.preventDefault();if(busy)return;if(!available){noteText.textContent='实时采集服务未连接。请在这台电脑运行 npm start 后使用本机网址。';return}const q={origin:$('#origin').value,outDate:$('#departure').value,backDate:returnDate($('#departure').value),earliest:$('#earliest').value,latest:$('#latest').value,destinations:cities.filter(c=>c.city!==$('#origin').value).map(c=>c.city)};job=null;render();lock(true);try{const res=await fetch('/api/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(q)}),data=await res.json();if(!res.ok)throw Error(data.error||'查询未能启动');job=data;render();void poll(job.id)}catch(e){lock(false);noteText.textContent=e.message}};
for(const id of ['origin','departure','earliest','latest'])$('#'+id).onchange=()=>{job=null;render()};$('#budget').oninput=render;$('#sort').onchange=render;$('#direct').checked=true;$('#direct').disabled=true;$('#direct').parentElement.title='当前版本只解析直飞航班';
$('#chips').onclick=e=>{const b=e.target.closest('[data-tag]');if(!b)return;tag=b.dataset.tag;document.querySelectorAll('[data-tag]').forEach(x=>x.classList.toggle('selected',x===b));render()};$('#discover').onclick=()=>{saved=false;$('#discover').classList.add('active');$('#favorites').classList.remove('active');render()};$('#favorites').onclick=()=>{saved=true;$('#favorites').classList.add('active');$('#discover').classList.remove('active');render()};$('#reset').onclick=()=>{tag='全部';saved=false;$('#budget').value=1200;render()};
$('#sort').querySelector('[value=duration]').remove();$('#sort').querySelector('[value=price]').textContent='含税价优先，未知税费按票面排序';lock(false);render();noteText.textContent='正在连接本机实时采集服务…';try{const res=await fetch('/api/health',{cache:'no-store'});const h=await res.json();available=h.mode==='live';noteText.textContent=available?'已连接飞猪 FlyAI。点击“查询全部目的地”，逐个查询当前去返程报价；不会使用演示价格。':'采集服务尚未就绪'}catch{noteText.textContent='当前网址未连接本机采集服务。请使用本机 http://127.0.0.1:4173/；这里不会显示演示价格。'}
window.addEventListener('live-render',()=>{try{favorites=JSON.parse(localStorage.getItem('weekend-favorites'))||[]}catch{}render()});
$('#departure').onchange=()=>{if(!$('#departure').value)return;$('#departure').value=weekend(new Date($('#departure').value+'T12:00:00'));job=null;render()};
try{const previous=JSON.parse(localStorage.getItem('weekend-last-live'));if(previous?.status==='complete'&&previous.query?.outDate>=new Date().toLocaleDateString('sv-SE')){job=previous;$('#origin').value=job.query.origin;$('#departure').value=job.query.outDate;$('#earliest').value=job.query.earliest;$('#latest').value=job.query.latest;noteText.textContent='已恢复上次查询结果。请查看采集时间；超过5分钟会标记为旧报价，点击查询可刷新。';render()}}catch{}
setInterval(render,60000);

